@import "tailwindcss";
@import "tw-animate-css";
@import "fumadocs-ui/css/shadcn.css";
@import "./themes.css";
@variant dark (&:is(.dark *));

:root {
  --radius: 0.875rem;
  --background: oklch(1.0 0.0 0.0);
  --foreground: oklch(0.37 0.04 257);

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.37 0.04 257);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.37 0.04 257);

  --primary: oklch(0.59 0.20 277);
  --primary-foreground: oklch(0.96 0.02 272);

  --secondary: oklch(98.42% 0.0034 247.86);
  --secondary-foreground: oklch(0.37 0.04 257);

  --muted: oklch(0.98 0.00 248);
  --muted-foreground: oklch(0.55 0.04 257);
  --muted-secondary: oklch(0.71 0.04 257);

  --accent: oklch(0.96 0.02 272);
  --accent-foreground: oklch(0.59 0.20 277);

  --destructive: oklch(0.64 0.21 25);
  --destructive-foreground: oklch(0.97 0.01 17);
  --success: oklch(0.70 0.15 162);
  --success-foreground: oklch(0.98 0.02 156);
  --warning: oklch(0.77 0.16 70);
  --warning-foreground: oklch(0.99 0.02 95);
  --info: oklch(0.62 0.19 260);
  --info-foreground: oklch(0.97 0.01 255);
  --inProgress: oklch(0.63 0.23 304);
  --inProgress-foreground: oklch(0.98 0.01 308);
  --link: oklch(0.68 0.15 237);
  --link-foreground: oklch(0.98 0.01 237);

  --border: oklch(0.93 0.01 256);
  --input: oklch(0.93 0.01 256);
  --ring: oklch(0.93 0.01 256);

  --sidebar: oklch(1.0 0.0 0.0);
  --sidebar-foreground: oklch(0.37 0.04 257);
  --sidebar-primary: oklch(0.37 0.04 257);
  --sidebar-primary-foreground: oklch(0.99 0.00 0);
  --sidebar-accent: oklch(0.96 0.02 272);
  --sidebar-accent-foreground: oklch(0.59 0.20 277);
  --sidebar-border: oklch(0.93 0.01 256);
  --sidebar-ring: oklch(0.93 0.01 256);

  --selection: oklch(0.96 0.02 272);
  --selection-foreground: oklch(0.59 0.20 277);

  --tooltip: oklch(0.68 0.16 277);  
  --tooltip-foreground: oklch(0.95 0.01 257);

  --chart-1: oklch(0.96 0.02 272);
  --chart-2: oklch(0.93 0.03 273);
  --chart-3: oklch(0.87 0.06 274);
  --chart-4: oklch(0.79 0.10 275);
  --chart-5: oklch(0.68 0.16 277);
  --chart-6: oklch(0.59 0.20 277);
  --chart-7: oklch(0.51 0.23 277);
  --chart-8: oklch(0.46 0.21 277);
  --chart-9: oklch(0.40 0.18 277);
  --chart-10: oklch(0.36 0.14 279);
  --chart-11: oklch(0.26 0.09 281);

  --font-weight-thin: 200;
  --font-weight-light: 300;
  --font-weight-normal: 400;
  --font-weight-medium: 450;
  --font-weight-semibold: 500;
  --font-weight-bold: 600;
}

.dark {
  --background: oklch(0.13 0.01 257);
  --foreground: oklch(0.95 0.01 257);

  --card: oklch(0.16 0.01 257);
  --card-foreground: oklch(0.95 0.01 257);

  --popover: oklch(0.16 0.01 257);
  --popover-foreground: oklch(0.95 0.01 257);

  --primary: oklch(0.59 0.20 277);
  --primary-foreground: oklch(0.96 0.02 272);

  --secondary: oklch(0.19 0.02 257);
  --secondary-foreground: oklch(0.70 0.08 277);

  --muted: oklch(0.19 0.01 257);
  --muted-foreground: oklch(0.60 0.03 257);
  --muted-secondary: oklch(0.71 0.04 257);

  --accent: oklch(0.26 0.09 281);
  --accent-foreground: oklch(0.68 0.16 277);

  --destructive: oklch(0.64 0.21 25);
  --destructive-foreground: oklch(0.97 0.01 17);
  --success: oklch(0.70 0.15 162);
  --success-foreground: oklch(0.98 0.02 156);
  --warning: oklch(0.77 0.16 70);
  --warning-foreground: oklch(0.99 0.02 95);
  --info: oklch(0.62 0.19 260);
  --info-foreground: oklch(0.97 0.01 255);
  --inProgress: oklch(0.63 0.23 304);
  --inProgress-foreground: oklch(0.98 0.01 308);
  --link: oklch(0.68 0.15 237);
  --link-foreground: oklch(0.98 0.01 237);

  --border: oklch(0.25 0.01 257);
  --input: oklch(0.25 0.01 257);
  --ring: oklch(0.59 0.20 277);

  --sidebar: oklch(0.13 0.01 257);
  --sidebar-foreground: oklch(0.95 0.01 257);
  --sidebar-primary: oklch(0.59 0.20 277);
  --sidebar-primary-foreground: oklch(0.13 0.01 257);
  --sidebar-accent: oklch(0.26 0.09 281);
  --sidebar-accent-foreground: oklch(0.68 0.16 277);
  --sidebar-border: oklch(0.25 0.01 257);
  --sidebar-ring: oklch(0.59 0.20 277);

  --selection: oklch(0.26 0.09 281);
  --selection-foreground: oklch(0.68 0.16 277);

  --tooltip: oklch(0.68 0.16 277);
  --tooltip-foreground: oklch(0.95 0.01 257);

  --chart-1: oklch(0.96 0.02 272);
  --chart-2: oklch(0.93 0.03 273);
  --chart-3: oklch(0.87 0.06 274);
  --chart-4: oklch(0.79 0.10 275);
  --chart-5: oklch(0.68 0.16 277);
  --chart-6: oklch(0.59 0.20 277);
  --chart-7: oklch(0.51 0.23 277);
  --chart-8: oklch(0.46 0.21 277);
  --chart-9: oklch(0.40 0.18 277);
  --chart-10: oklch(0.36 0.14 279);
  --chart-11: oklch(0.26 0.09 281);

  --font-weight-thin: 100;
  --font-weight-light: 200;
  --font-weight-normal: 300;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);

  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);

  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted-secondary: var(--muted-secondary);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --color-inProgress: var(--inProgress);
  --color-inProgress-foreground: var(--inProgress-foreground);
  --color-link: var(--link);
  --color-link-foreground: var(--link-foreground);

  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-chart-6: var(--chart-6);
  --color-chart-7: var(--chart-7);
  --color-chart-8: var(--chart-8);
  --color-chart-9: var(--chart-9);
  --color-chart-10: var(--chart-10);
  --color-chart-11: var(--chart-11);

  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  --color-selection: var(--selection);
  --color-selection-foreground: var(--selection-foreground);

  --color-tooltip: var(--tooltip);
  --color-tooltip-foreground: var(--tooltip-foreground);

  --font-sans: var(--font-sans);
  --font-serif: var(--font-serif);
  --font-mono: var(--font-mono);

  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --shadow-2xs: var(--shadow-2xs);
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow: var(--shadow);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-xl: var(--shadow-xl);
  --shadow-2xl: var(--shadow-2xl);

  --font-weight-thin: var(--font-weight-thin);
  --font-weight-light: var(--font-weight-light);
  --font-weight-normal: var(--font-weight-normal);
  --font-weight-medium: var(--font-weight-medium);
  --font-weight-semibold: var(--font-weight-semibold);
  --font-weight-bold: var(--font-weight-bold);
}
@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  ::selection {
    @apply bg-selection text-selection-foreground;
  }
  html {
    @apply scroll-smooth;
  }
  body {
    font-synthesis-weight: none;
    text-rendering: optimizeLegibility;
  }

  @supports (font: -apple-system-body) and (-webkit-appearance: none) {
    [data-wrapper] {
      @apply min-[1800px]:border-t;
    }
  }

  a:active,
  button:active {
    @apply opacity-60 md:opacity-100;
  }
}

@layer components {
  .steps {
    &:first-child {
      @apply !mt-0;
    }

    &:first-child > h3:first-child {
      @apply !mt-0;
    }

    > h3 {
      @apply !mt-16;
    }

    > h3 + p {
      @apply !mt-2;
    }
  }

  [data-rehype-pretty-code-figure] {
    background-color: var(--color-code);
    color: var(--color-code-foreground);
    border-radius: var(--radius-xl);
    border-width: 1px;
    border-color: var(--border);
    margin-top: calc(var(--spacing) * 6);
    overflow: hidden;
    font-size: var(--text-xs);
    outline: none;
    position: relative;
    @apply -mx-1 md:-mx-1;

    &:has([data-rehype-pretty-code-title]) [data-slot="copy-button"] {
      top: calc(var(--spacing) * 1.5) !important;
    }
  }

  [data-rehype-pretty-code-title] {
    border-bottom: color-mix(in oklab, var(--border) 30%, transparent);
    border-bottom-width: 1px;
    border-bottom-style: solid;
    padding-block: calc(var(--spacing) * 2.5);
    padding-inline: calc(var(--spacing) * 4);
    font-size: var(--text-sm);
    font-family: var(--font-mono);
    color: var(--color-code-foreground);
  }

  [data-line-numbers] {
    display: grid;
    min-width: 100%;
    white-space: pre;
    border: 0;
    background: transparent;
    padding: 0;
    counter-reset: line;
    box-decoration-break: clone;
  }

  [data-line-numbers] [data-line]::before {
    font-size: var(--text-xs);
    counter-increment: line;
    content: counter(line);
    display: inline-block;
    width: calc(var(--spacing) * 16);
    padding-right: calc(var(--spacing) * 6);
    text-align: right;
    color: var(--color-code-number);
    background-color: var(--color-code);
    position: sticky;
    left: 0;
  }

  [data-line-numbers] [data-highlighted-line][data-line]::before {
    background-color: var(--color-code-highlight);
  }

  [data-line] {
    padding-top: calc(var(--spacing) * 0.5);
    padding-bottom: calc(var(--spacing) * 0.5);
    min-height: calc(var(--spacing) * 1);
    width: 100%;
    display: inline-block;
  }

  [data-line] span {
    color: var(--shiki-light);

    @variant dark {
      color: var(--shiki-dark) !important;
    }
  }

  [data-highlighted-line],
  [data-highlighted-chars] {
    position: relative;
    background-color: var(--color-code-highlight);
  }

  [data-highlighted-line] {
    &:after {
      position: absolute;
      top: 0;
      left: 0;
      width: 2px;
      height: 100%;
      content: "";
      background-color: color-mix(
        in oklab,
        var(--muted-foreground) 50%,
        transparent
      );
    }
  }

  [data-highlighted-chars] {
    border-radius: var(--radius-sm);
    padding-inline: 0.3rem;
    padding-block: 0.1rem;
    font-family: var(--font-mono);
    font-size: 0.8rem;
  }
}

/* ENHANCED SCROLLBAR HIDING - Multiple approaches for maximum compatibility */

/* Hide scrollbars for Webkit browsers (Chrome, Safari, Edge) */
::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  background: transparent !important;
}

::-webkit-scrollbar-track {
  display: none !important;
}

::-webkit-scrollbar-thumb {
  display: none !important;
}

::-webkit-scrollbar-corner {
  display: none !important;
}

/* Hide scrollbars for Firefox */
* {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

html {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

body {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  overscroll-behavior-y: none;
  background-color: var(--color-fd-background);
}
div, section, article, main, aside, nav, header, footer {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

div::-webkit-scrollbar,
section::-webkit-scrollbar,
article::-webkit-scrollbar,
main::-webkit-scrollbar,
aside::-webkit-scrollbar,
nav::-webkit-scrollbar,
header::-webkit-scrollbar,
footer::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

/* Target specific overflow containers */
[style*="overflow"],
.overflow-auto,
.overflow-scroll,
.overflow-x-auto,
.overflow-y-auto,
.overflow-x-scroll,
.overflow-y-scroll {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

[style*="overflow"]::-webkit-scrollbar,
.overflow-auto::-webkit-scrollbar,
.overflow-scroll::-webkit-scrollbar,
.overflow-x-auto::-webkit-scrollbar,
.overflow-y-auto::-webkit-scrollbar,
.overflow-x-scroll::-webkit-scrollbar,
.overflow-y-scroll::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
    print-color-adjust: exact;
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
  }

  *::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
  }

  html {
    text-rendering: optimizelegibility;
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
  }

  html::-webkit-scrollbar {
    display: none !important;
  }

  body {
    @apply bg-background text-foreground;
    font-feature-settings: 'rlig' 1, 'calt' 1;
    overflow-wrap: break-word;
    word-break: break-word;
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
  }

  body::-webkit-scrollbar {
    display: none !important;
  }

}
button:not(:disabled),
[role="button"]:not(:disabled) {
  @apply cursor-pointer;
}

/* Hide scrollbars for Webkit browsers (Chrome, Safari, Edge) */
::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

::-webkit-scrollbar-track {
  display: none !important;
}

::-webkit-scrollbar-thumb {
  display: none !important;
}

::-webkit-scrollbar-corner {
  display: none !important;
}

/* Hide scrollbars for Firefox */
* {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

html {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

body {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  overscroll-behavior-y: none;
}

/* Hide content until theme is loaded to prevent FOUC */
body.theme-loading {
  opacity: 0;
  visibility: hidden;
}
/* Scope TOC navigation to only appear within docs page, not above sidebar */
[data-slot="docs"] #nd-tocnav {
  @apply visible;
  margin-top: 48px;
  /* Offset from left to account for sidebar width */
  @apply lg:ml-[var(--sidebar-width)];
  /* Constrain width to exclude sidebar */
  @apply lg:w-[calc(100%-var(--sidebar-width))];
}

/* Hide the standalone TOC */
#nd-toc {
  @apply hidden;
}
/* Loader Animations */
@keyframes typing {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.5;
  }
  50% {
    transform: translateY(-2px);
    opacity: 1;
  }
}

@keyframes loading-dots {
  0%,
  100% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
}

@keyframes wave {
  0%,
  100% {
    transform: scaleY(1);
  }
  50% {
    transform: scaleY(0.6);
  }
}

@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@keyframes text-blink {
  0%,
  100% {
    color: var(--primary);
  }
  50% {
    color: var(--muted-foreground);
  }
}

@keyframes bounce-dots {
  0%,
  100% {
    transform: scale(0.8);
    opacity: 0.5;
  }
  50% {
    transform: scale(1.2);
    opacity: 1;
  }
}

@keyframes thin-pulse {
  0%,
  100% {
    transform: scale(0.95);
    opacity: 0.8;
  }
  50% {
    transform: scale(1.05);
    opacity: 0.4;
  }
}

@keyframes pulse-dot {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.8;
  }
  50% {
    transform: scale(1.5);
    opacity: 1;
  }
}

@keyframes shimmer-text {
  0% {
    background-position: 150% center;
  }
  100% {
    background-position: -150% center;
  }
}

@keyframes wave-bars {
  0%,
  100% {
    transform: scaleY(1);
    opacity: 0.5;
  }
  50% {
    transform: scaleY(0.6);
    opacity: 1;
  }
}

@keyframes shimmer {
  0% {
    background-position: 200% 50%;
  }
  100% {
    background-position: -200% 50%;
  }
}

@keyframes spinner-fade {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

@layer components {
  .steps {
    &:first-child {
      @apply !mt-0;
    }

    &:first-child > h3:first-child {
      @apply !mt-0;
    }

    > h3 {
      @apply !mt-16;
    }

    > h3 + p {
      @apply !mt-2;
    }
  }

}

/* themes.css — unified structure for all themes
   Each theme defines the same variable set plus a @variant dark block.
   Charts map 1..11 to the 50..950 steps of the theme color scale. */

/* === Default (Indigo) ===================================================== */
.theme-default {
  --primary: var(--color-indigo-600);
  --primary-foreground: var(--color-indigo-50);
  --accent: var(--color-indigo-50);
  --accent-foreground: var(--color-indigo-600);
  --sidebar-accent: var(--color-indigo-50);
  --sidebar-accent-foreground: var(--color-indigo-500);
  --selection: var(--color-indigo-50);
  --selection-foreground: var(--color-indigo-600);
  --tooltip: var(--color-indigo-400);
  --tooltip-foreground: var(--color-indigo-100);

  --chart-1: var(--color-indigo-50);
  --chart-2: var(--color-indigo-100);
  --chart-3: var(--color-indigo-200);
  --chart-4: var(--color-indigo-300);
  --chart-5: var(--color-indigo-400);
  --chart-6: var(--color-indigo-500);
  --chart-7: var(--color-indigo-600);
  --chart-8: var(--color-indigo-700);
  --chart-9: var(--color-indigo-800);
  --chart-10: var(--color-indigo-900);
  --chart-11: var(--color-indigo-950);

  @variant dark {
    --primary: var(--color-indigo-500);
    --primary-foreground: var(--color-indigo-50);
    --accent: var(--color-indigo-950);
    --accent-foreground: var(--color-indigo-400);
    --sidebar-accent: var(--color-indigo-950);
    --sidebar-accent-foreground: var(--color-indigo-400);
    --selection: var(--color-indigo-950);
    --selection-foreground: var(--color-indigo-400);
    --tooltip: var(--color-indigo-800);
    --tooltip-foreground: var(--color-indigo-200);

    --chart-1: var(--color-indigo-50);
    --chart-2: var(--color-indigo-100);
    --chart-3: var(--color-indigo-200);
    --chart-4: var(--color-indigo-300);
    --chart-5: var(--color-indigo-400);
    --chart-6: var(--color-indigo-500);
    --chart-7: var(--color-indigo-600);
    --chart-8: var(--color-indigo-700);
    --chart-9: var(--color-indigo-800);
    --chart-10: var(--color-indigo-900);
    --chart-11: var(--color-indigo-950);
  }
}

/* === Red ================================================================== */
.theme-red {
  --primary: var(--color-red-600);
  --primary-foreground: var(--color-red-50);
  --accent: var(--color-red-50);
